namespace ghidra.app.plugin.debug.propertymanager;

using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.util;
using ghidra.program.model.util;





/*
 * PropertyManagerTableModel
 */
class PropertyManagerTableModel : AbstractTableModel {
	private static readonly long serialVersionUID = 1L;

	static readonly int PROPERTY_NAME_COLUMN = 0;

	string[] propertyNames;

	/**
	 * @param currentProgram
	 * @param currentSelection
	 * @param searchMarks
	 */
	public void update(Program program, AddressSetView addrSet) {
		bool restrictedView = (addrSet != null && !addrSet.isEmpty()); 
		List<string> list = new List<string>();

		if (program != null) {
			PropertyMapManager propMgr = program.getUsrPropertyManager();
			Iterator<string> iter = propMgr.propertyManagers();
			while (iter.hasNext()) {
				string name = iter.next();
				if (restrictedView) {
					PropertyMap map = propMgr.getPropertyMap(name);
					if (map.intersects(addrSet)) {
						list.add(name);
					}
				}
				else {
					list.add(name);	
				}
			}
		}
		propertyNames = new string[list.size()];
		list.toArray(propertyNames);
		Arrays.sort(propertyNames);

		fireTableDataChanged();
	}

	/*
	 * @see javax.swing.table.TableModel#getColumnCount()
	 */
	/* @Override */
	public int getColumnCount() {
		return 1;
	}

	/*
	 * @see javax.swing.table.TableModel#getRowCount()
	 */
	/* @Override */
	public int getRowCount() {
		if (propertyNames != null) {
			return propertyNames.length;	
		}
		return 0;
	}
	
	/*
	 * @see javax.swing.table.TableModel#getColumnName(int)
	 */
	/* @Override */
    public string getColumnName(int column) {
		return "Property Name";
	}

	/*
	 * @see javax.swing.table.TableModel#getValueAt(int, int)
	 */
	/* @Override */
	public object getValueAt(int rowIndex, int columnIndex) {
		if (propertyNames != null && rowIndex < propertyNames.length) {	
			return propertyNames[rowIndex];
		}
		return null;
	}

	/**
	 * @param row
	 */
	protected void removeRow(int row) {
		if (propertyNames == null || row >= propertyNames.length) {
			return;
		}
		string[] newList = new string[propertyNames.length-1];
		Array.Copy(propertyNames, 0, newList, 0, row);
		Array.Copy(propertyNames, row+1, newList, row, newList.length-row);
		propertyNames = newList;
		fireTableDataChanged();
	}

}



